/**
 * relay/worker.js — Cloudflare Worker + Durable Object for the Realot ⇄ AI bridge.
 *
 *   AI app (MCP connector)  --POST /mcp/<key>-->  Worker  -->  BridgeRoom (Durable Object)
 *   Realot editor tab       --WebSocket /bridge/<key>-->  same BridgeRoom
 *
 * <key> is a 64-hex secret generated by the editor. Whoever knows it can drive
 * that editor session, so treat the connector URL like a password.
 */
import { handleMcpBody, KEY_PATTERN, NOT_CONNECTED_MESSAGE } from "./mcp-core.js";

const CALL_TIMEOUT_MS = 25_000;
const MAX_MCP_BODY = 256 * 1024;       // Asset bytes travel as 180 KiB chunks to stay below this cap.
const MAX_EDITOR_MESSAGE = 2_000_000;  // screenshots (~300 KB) are the largest reply; keeps CPU well inside the free plan's 10 ms
const MAX_CALLS_PER_MINUTE = 90;       // per user key — protects the shared free quota


// CORS so browser-based AI apps / inspectors can call the MCP endpoint too.
const CORS = {
  "access-control-allow-origin": "*",
  "access-control-allow-methods": "POST, GET, DELETE, OPTIONS",
  "access-control-allow-headers": "content-type, authorization, mcp-session-id, mcp-protocol-version, accept",
  "access-control-expose-headers": "mcp-session-id",
  "access-control-max-age": "86400",
};
const withCors = (res) => {
  const h = new Headers(res.headers);
  for (const [k, v] of Object.entries(CORS)) h.set(k, v);
  return new Response(res.body, { status: res.status, statusText: res.statusText, headers: h });
};

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const parts = url.pathname.split("/").filter(Boolean);

    if (parts.length === 0) {
      return new Response("Realot bridge relay is running.\nAdd https://<this-host>/mcp/<your-key> as a custom connector in any AI app that supports MCP connectors.\n", {
        headers: { "content-type": "text/plain" },
      });
    }

    const [kind, key] = parts;
    if ((kind !== "mcp" && kind !== "bridge") || !KEY_PATTERN.test(key || "")) {
      return new Response("Not found", { status: 404 });
    }

    if (kind === "bridge") {
      if (request.headers.get("Upgrade") !== "websocket") return new Response("Expected WebSocket", { status: 426 });
      // Optional: only let YOUR site's editor use this relay (set ALLOWED_ORIGINS in wrangler.toml).
      const allowed = String(env.ALLOWED_ORIGINS || "").split(",").map((s) => s.trim()).filter(Boolean);
      if (allowed.length && !allowed.includes(request.headers.get("Origin") || "")) return new Response("Origin not allowed", { status: 403 });
      const room = env.ROOM.get(env.ROOM.idFromName(key));
      return room.fetch(new Request("https://room/bridge", request));
    }

    // kind === "mcp"
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: CORS });
    if (request.method === "GET") return withCors(new Response("This MCP server uses POST only.", { status: 405, headers: { Allow: "POST" } }));
    if (request.method === "DELETE") return withCors(new Response(null, { status: 200 }));
    if (request.method !== "POST") return withCors(new Response("Method not allowed", { status: 405 }));

    const raw = await request.text();
    if (raw.length > MAX_MCP_BODY) return withCors(new Response("Request too large", { status: 413 }));
    const room = env.ROOM.get(env.ROOM.idFromName(key));
    const result = await handleMcpBody(raw, {
      callEditor: async (tool, args) => {
        const res = await room.fetch("https://room/call", { method: "POST", body: JSON.stringify({ tool, args }) });
        const data = await res.json();
        if (!res.ok) throw new Error(data.error || "Editor call failed");
        return data;
      },
    });
    return withCors(new Response(result.body === null ? null : JSON.stringify(result.body), {
      status: result.status,
      headers: { "content-type": "application/json" },
    }));
  },
};

/**
 * One BridgeRoom per user key. Uses the WebSocket Hibernation API so the
 * object is NOT kept in memory (and billed for duration) while the editor tab
 * is merely open and idle — this is what keeps the free plan's daily limits
 * from being eaten by a single connected editor. Heartbeat pings are answered
 * by the runtime without waking the object.
 */
export class BridgeRoom {
  constructor(state, env) {
    this.state = state;
    this.pending = new Map(); // id -> { resolve, timer }   (only lives while a call is in flight)
    this.nextId = 1;
    this.recent = []; // timestamps of recent tool calls (rate limit)
    try {
      this.state.setWebSocketAutoResponse(new WebSocketRequestResponsePair('{"type":"ping"}', '{"type":"pong"}'));
    } catch { /* older runtimes: pings are then answered in webSocketMessage */ }
  }

  editorSocket(except) {
    return this.state.getWebSockets().find((s) => s !== except && s.readyState === 1) || null;
  }

  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname === "/bridge") {
      const pair = new WebSocketPair();
      const [client, server] = Object.values(pair);
      // Newest editor tab wins; close the previous one.
      for (const old of this.state.getWebSockets()) { try { old.close(1000, "replaced by a newer connection"); } catch {} }
      this.state.acceptWebSocket(server);
      return new Response(null, { status: 101, webSocket: client });
    }

    if (url.pathname === "/call") {
      const socket = this.editorSocket();
      if (!socket) return Response.json({ isError: true, text: NOT_CONNECTED_MESSAGE });
      let payload;
      try { payload = await request.json(); } catch { return Response.json({ isError: true, text: "Bad request." }); }
      const { tool, args } = payload;
      const now = Date.now();
      this.recent = this.recent.filter((t) => now - t < 60_000);
      if (this.recent.length >= MAX_CALLS_PER_MINUTE) {
        return Response.json({ isError: true, text: "Too many tool calls in the last minute (limit " + MAX_CALLS_PER_MINUTE + "). Wait a moment and continue." });
      }
      this.recent.push(now);
      const id = this.nextId++;
      const result = await new Promise((resolve) => {
        const timer = setTimeout(() => {
          this.pending.delete(id);
          resolve({ isError: true, text: "The editor did not answer within " + CALL_TIMEOUT_MS / 1000 + " seconds." });
        }, CALL_TIMEOUT_MS);
        this.pending.set(id, { resolve, timer });
        try { socket.send(JSON.stringify({ type: "call", id, tool, args })); }
        catch { clearTimeout(timer); this.pending.delete(id); resolve({ isError: true, text: NOT_CONNECTED_MESSAGE }); }
      });
      return Response.json(result);
    }
    return new Response("Not found", { status: 404 });
  }

  // ---- Hibernation API handlers
  async webSocketMessage(ws, data) {
    if (typeof data !== "string") return;
    if (data.length > MAX_EDITOR_MESSAGE) { try { ws.close(1009, "message too large"); } catch {} return; }
    let msg;
    try { msg = JSON.parse(data); } catch { return; }
    if (msg.type === "ping") { try { ws.send('{"type":"pong"}'); } catch {} return; }
    if (msg.type !== "result") return;
    const p = this.pending.get(msg.id);
    if (!p) return;
    clearTimeout(p.timer);
    this.pending.delete(msg.id);
    p.resolve({ content: msg.content, isError: !!msg.isError, text: msg.text });
  }

  async webSocketClose(ws) {
    try { ws.close(1000, "closed"); } catch {}
    this.gone(ws);
  }

  async webSocketError(ws) {
    this.gone(ws);
  }

  gone(ws) {
    // A replaced tab closing must not fail calls that the newer tab is serving.
    if (this.editorSocket(ws)) return;
    for (const [id, p] of this.pending) { clearTimeout(p.timer); p.resolve({ isError: true, text: NOT_CONNECTED_MESSAGE }); this.pending.delete(id); }
  }
}
